SELECT *
FROM automation_ui_scene
WHERE id > #{afterId}
  AND (debug_record IS NOT NULL OR test_record IS NOT NULL)
ORDER BY id
LIMIT #{limit}

SELECT s.id, COALESCE(es.update_time, s.update_time) AS update_time, COALESCE(es.execution_revision, 0) AS execution_revision FROM automation_ui_scene s LEFT JOIN automation_ui_scene_execution_state es ON es.scene_id = s.id WHERE s.id IN
#{id}
ORDER BY s.id
